  red:     "EF4444",
  green:   "22C55E",
};

// ─── Helper: dark footer bar ──────────────────────────────────────────────────
function addFooter(slide, label) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.3, w: 10, h: 0.325,
    fill: { color: C.mid }, line: { color: C.mid }
  });
