    x: 0.3, y: 5.32, w: 6, h: 0.28, fontSize: 9,
    color: "64748B", align: "left", valign: "middle", margin: 0
  });
  if (label) {
    slide.addText(label, {
      x: 7, y: 5.32, w: 2.7, h: 0.28, fontSize: 9,
      color: "64748B", align: "right", valign: "middle", margin: 0
    });
  }
}

// ─── Helper: accent left bar ──────────────────────────────────────────────────
function accentBar(slide, x, y, h, color) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.06, h,
    fill: { color: color || C.teal }, line: { color: color || C.teal }
  });
}

