const pptxgen = require("pptxgenjs");
const fs = require("fs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "DiaTool-DPO: Enhancing Tool-Augmented LLM Dialogue via Direct Preference Optimization";

// ─── Palette ─────────────────────────────────────────────────────────────────
const C = {
  dark:    "0F172A",  // slide BG (dark slides)
  mid:     "1E293B",  // panel BG
  light:   "F1F5F9",  // content slide BG
  lightPan:"FFFFFF",  // card BG
  teal:    "0D9488",  // primary accent
  tealLt:  "5EEAD4",  // light teal
  amber:   "F59E0B",  // highlight accent
  slate:   "475569",  // muted text
  white:   "FFFFFF",
  black:   "0F172A",
  textDark:"1E293B",
  textMid: "334155",
  red:     "EF4444",
  green:   "22C55E",
};

// ─── Helper: dark footer bar ──────────────────────────────────────────────────
function addFooter(slide, label) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.3, w: 10, h: 0.325,
    fill: { color: C.mid }, line: { color: C.mid }
  });
  slide.addText("DiaTool-DPO  •  arxiv 2504.02882", {
    x: 0.3, y: 5.32, w: 6, h: 0.28, fontSize: 9,
    color: "64748B", align: "left", valign: "middle", margin: 0
  });
  if (label) {
    slide.addText(label, {
      x: 7, y: 5.32, w: 2.7, h: 0.28, fontSize: 9,
      color: "64748B", align: "right", valign: "middle", margin: 0
    });
  }
}

// ─── Helper: accent left bar ──────────────────────────────────────────────────
function accentBar(slide, x, y, h, color) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x, y, w: 0.06, h,
    fill: { color: color || C.teal }, line: { color: color || C.teal }
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.dark };

  // Teal left strip
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 0.25, h: 5.625,
    fill: { color: C.teal }, line: { color: C.teal }
  });

  // Subtle mid panel
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.25, y: 1.5, w: 9.75, h: 2.65,
    fill: { color: C.mid }, line: { color: C.mid }
  });

  // Main title
  s.addText("DiaTool-DPO", {
    x: 0.55, y: 1.6, w: 9, h: 0.95,
    fontSize: 44, bold: true, color: C.tealLt,
    fontFace: "Trebuchet MS", align: "left", margin: 0
  });

  s.addText("Enhancing Tool-Augmented LLM Dialogue", {
    x: 0.55, y: 2.55, w: 9, h: 0.5,
    fontSize: 22, bold: false, color: C.white,
    fontFace: "Calibri", align: "left", margin: 0
  });

  s.addText("via Direct Preference Optimization", {
    x: 0.55, y: 3.0, w: 9, h: 0.45,
    fontSize: 22, bold: false, color: C.white,
    fontFace: "Calibri", align: "left", margin: 0
  });

  // Tagline
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.55, y: 3.65, w: 6.5, h: 0.55,
    fill: { color: C.teal }, line: { color: C.teal }
  });
  s.addText("5-State MDP  ·  Automatic Pair Construction  ·  Near GPT-4o Performance", {
    x: 0.6, y: 3.67, w: 6.4, h: 0.5,
    fontSize: 12, color: C.white, fontFace: "Calibri",
    align: "center", valign: "middle", margin: 0
  });

  s.addText("ML Researchers & NLP Engineers | Tool-Augmented LLMs & RLHF Alignment", {
    x: 0.55, y: 4.4, w: 9, h: 0.35,
    fontSize: 11, color: "64748B", fontFace: "Calibri",
    align: "left", margin: 0
  });
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 2 — Problem & Motivation
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.light };

  // Title band
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.85,
    fill: { color: C.dark }, line: { color: C.dark }
  });
  s.addText("SFT Alone Fails to Teach Slot-Filling and Tool Rejection", {
    x: 0.35, y: 0.08, w: 9.3, h: 0.7,
    fontSize: 21, bold: true, color: C.white,
    fontFace: "Trebuchet MS", align: "left", valign: "middle", margin: 0
  });

  // Context blurb
  s.addText("TA-LLMs trained only with SFT on expert trajectories struggle with real-world incomplete queries and out-of-scope requests, causing hallucinated tool invocations.", {
    x: 0.35, y: 0.95, w: 9.3, h: 0.55,
    fontSize: 13, color: C.textMid, fontFace: "Calibri",
    align: "left", margin: 0
  });

  // Three failure mode cards
  const cards = [
    { title: "Failure Mode 1", sub: "Missing Slot-Filling", body: "When user queries lack required arguments, SFT models skip clarifying questions and attempt tool calls with incomplete parameters.", color: C.red },
    { title: "Failure Mode 2", sub: "Hallucinated Tool Calls", body: "Without preference feedback, models fabricate argument values rather than requesting missing information from the user.", color: C.amber },
    { title: "Failure Mode 3", sub: "Unrejected Out-of-Scope", body: "SFT models fail to reject tool calls when no suitable tool exists, producing invalid invocations for unsupported functionality.", color: "7C3AED" },
  ];

  cards.forEach((c, i) => {
    const x = 0.3 + i * 3.15;
    s.addShape(pres.shapes.RECTANGLE, {
      x, y: 1.6, w: 3.0, h: 2.85,
      fill: { color: C.lightPan }, line: { color: "E2E8F0", pt: 1 },
      shadow: { type: "outer", blur: 8, offset: 2, angle: 135, color: "000000", opacity: 0.08 }
    });
    // Color accent top
    s.addShape(pres.shapes.RECTANGLE, {
      x, y: 1.6, w: 3.0, h: 0.12,
      fill: { color: c.color }, line: { color: c.color }
    });
    s.addText(c.title, {
      x: x + 0.15, y: 1.75, w: 2.7, h: 0.3,
      fontSize: 10, color: c.color, bold: true,
      fontFace: "Calibri", align: "left", margin: 0
    });
    s.addText(c.sub, {
      x: x + 0.15, y: 2.07, w: 2.7, h: 0.35,
      fontSize: 14, color: C.textDark, bold: true,
      fontFace: "Trebuchet MS", align: "left", margin: 0
    });
    s.addText(c.body, {
      x: x + 0.15, y: 2.5, w: 2.7, h: 1.75,
      fontSize: 12, color: C.textMid, fontFace: "Calibri",
      align: "left", valign: "top", margin: 0
    });
  });

  // Solution callout
  s.addShape(pres.shapes.RECTANGLE, {
    x: 0.3, y: 4.6, w: 9.4, h: 0.52,
    fill: { color: "ECFDF5" }, line: { color: C.teal, pt: 1 }
  });
  s.addText("Solution: DiaTool-DPO models TA-LLM dialogue as a 5-state MDP and uses DPO with automatically constructed trajectory pairs to teach preference between correct and incorrect dialogue flows.", {
    x: 0.45, y: 4.63, w: 9.1, h: 0.45,
    fontSize: 11.5, color: "065F46", fontFace: "Calibri",
    align: "left", valign: "middle", margin: 0
  });

  addFooter(s, "Slide 2 / 8");
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 3 — 5-State MDP
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.light };

  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.85,
    fill: { color: C.dark }, line: { color: C.dark }
  });
  s.addText("Modeling TA-LLM Dialogue as a 5-State Markov Decision Process", {
    x: 0.35, y: 0.08, w: 9.3, h: 0.7,
    fontSize: 20, bold: true, color: C.white,
    fontFace: "Trebuchet MS", align: "left", valign: "middle", margin: 0
  });

  // State boxes — horizontal flow
  const states = [
    { num: "S1", label: "Initial", desc: "No history; rejects out-of-scope requests here" },
    { num: "S2", label: "Tool Selected\nw/o Complete Slots", desc: "Tool identified; slot-filling QA repeats N times" },
    { num: "S3", label: "Tool Selected\nw/ Complete Slots", desc: "All args determined; ready to call" },
    { num: "S4", label: "Wait for\nTool Response", desc: "Tool called; awaiting result" },
    { num: "S5", label: "Complete", desc: "Results received; user reply generated" },
  ];

  const boxW = 1.62, boxH = 1.65, startX = 0.25, y = 1.1, gap = 0.18;
  states.forEach((st, i) => {
    const x = startX + i * (boxW + gap);
    s.addShape(pres.shapes.RECTANGLE, {
      x, y, w: boxW, h: boxH,
      fill: { color: i === 0 ? C.teal : (i === 4 ? "065F46" : C.mid) },
      line: { color: i === 0 ? C.teal : (i === 4 ? "065F46" : "334155"), pt: 1 },
      shadow: { type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.15 }
    });
    s.addText(st.num, {
      x: x + 0.08, y: y + 0.1, w: 0.5, h: 0.35,
      fontSize: 16, bold: true, color: C.tealLt,
      fontFace: "Trebuchet MS", align: "left", margin: 0
    });
    s.addText(st.label, {
      x: x + 0.08, y: y + 0.43, w: boxW - 0.16, h: 0.55,
      fontSize: 12, bold: true, color: C.white,
      fontFace: "Trebuchet MS", align: "left", margin: 0
    });
    s.addText(st.desc, {
      x: x + 0.08, y: y + 0.98, w: boxW - 0.16, h: 0.62,
      fontSize: 10, color: "94A3B8", fontFace: "Calibri",
      align: "left", margin: 0
    });

    // Arrow between boxes
    if (i < states.length - 1) {
      const ax = x + boxW;
      s.addShape(pres.shapes.LINE, {
        x: ax, y: y + boxH / 2, w: gap, h: 0,
        line: { color: C.teal, width: 2 }
      });
    }
  });

  // Transition labels row
  const transitions = [
    { label: "reject\n→ stay", x: 0.25, color: C.red },
    { label: "slot-fill\nloop ×N", x: 2.05, color: C.amber },
    { label: "args\ncomplete", x: 3.85, color: C.tealLt },
    { label: "tool\ncall", x: 5.65, color: C.tealLt },
    { label: "generate\nreply", x: 7.45, color: C.tealLt },
  ];
  transitions.forEach((t) => {
    s.addText(t.label, {
      x: t.x, y: 2.95, w: 1.62, h: 0.5,
      fontSize: 10, color: t.color, fontFace: "Calibri",
      align: "center", italic: true, margin: 0
    });
  });

  // Self-loop note for S1
  s.addText("S1 → S1 : Out-of-scope requests return a rejection and stay in Initial state (Type 3 query)", {
    x: 0.3, y: 3.58, w: 9.4, h: 0.38,
    fontSize: 11, color: C.textMid, fontFace: "Calibri",
    align: "left", italic: true, margin: 0
  });

  // S2 loop note
  s.addText("S2 loop : Slot-filling QA repeats N times (S1 → S2 → … → S2 → S3) until all required parameters are gathered (Type 2 query)", {
    x: 0.3, y: 3.98, w: 9.4, h: 0.38,
    fontSize: 11, color: C.textMid, fontFace: "Calibri",
    align: "left", italic: true, margin: 0
  });

  // Type 1 note
  s.addText("Type 1 fast-path: S1 → S3 → S4 → S5  (all arguments supplied upfront; no slot-filling needed)", {
    x: 0.3, y: 4.38, w: 9.4, h: 0.38,
    fontSize: 11, color: C.textMid, fontFace: "Calibri",
    align: "left", italic: true, margin: 0
  });

  addFooter(s, "Slide 3 / 8");
}

// ══════════════════════════════════════════════════════════════════════════════
// SLIDE 4 — Three Query Types
// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.light };

  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.85,
    fill: { color: C.dark }, line: { color: C.dark }
  });
  s.addText("Three Query Types Define Distinct State Trajectories", {
    x: 0.35, y: 0.08, w: 9.3, h: 0.7,
    fontSize: 21, bold: true, color: C.white,
    fontFace: "Trebuchet MS", align: "left", valign: "middle", margin: 0
  });

  // Table header
  const colX = [0.3, 2.35, 4.8, 7.1];
  const colW = [1.95, 2.35, 2.2, 2.65];
  const headers = ["Query Type", "State Trajectory", "Slot-Filling?", "Example Scenario"];
  const headerBg = C.teal;

  headers.forEach((h, i) => {
    s.addShape(pres.shapes.RECTANGLE, {
      x: colX[i], y: 1.0, w: colW[i], h: 0.42,
      fill: { color: headerBg }, line: { color: headerBg }
    });
    s.addText(h, {
      x: colX[i] + 0.08, y: 1.02, w: colW[i] - 0.16, h: 0.38,
