      fontFace: "Trebuchet MS", align: "left", valign: "middle", margin: 0
    });
  });

  const rows = [
    {
      type: "Type 1",
      traj: "1 → 3 → 4 → 5",
      slot: "No – all args\nprovided upfront",
      example: "\"Book a flight from Seoul to Tokyo on May 1\" (origin, dest, date all present)",
      rowColor: "F0FDF4",
      accent: C.teal,
    },
    {
      type: "Type 2",
      traj: "1 → (2×N) → 3 → 4 → 5",
      slot: "Yes – N rounds\nof slot-filling QA",
      example: "\"Book a flight\" (missing origin, destination, date → model asks N clarifying questions)",
      rowColor: "FFFBEB",
      accent: C.amber,
    },
    {
      type: "Type 3",
      traj: "1 → 1",
      slot: "N/A – request\nrejected",
      example: "\"Write me a poem\" (no suitable tool available → model returns rejection message)",
