  rows.forEach((r, i) => {
    const ry = 1.42 + i * 1.0;
    const rowH = 0.92;

    // Row background
    s.addShape(pres.shapes.RECTANGLE, {
      x: colX[0], y: ry, w: 9.45, h: rowH,
      fill: { color: r.rowColor }, line: { color: "E2E8F0", pt: 1 }
    });
    // Accent left
    s.addShape(pres.shapes.RECTANGLE, {
      x: colX[0], y: ry, w: 0.07, h: rowH,
