// ══════════════════════════════════════════════════════════════════════════════
{
  const s = pres.addSlide();
  s.background = { color: C.light };

  s.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.85,
    fill: { color: C.dark }, line: { color: C.dark }
  });
  s.addText("Automatic Paired Trajectory Construction — No Human Labels", {
    x: 0.35, y: 0.08, w: 9.3, h: 0.7,
    fontSize: 21, bold: true, color: C.white,
    fontFace: "Trebuchet MS", align: "left", valign: "middle", margin: 0
  });

  // Concept line
  s.addText("Each DPO pair: Chosen (correct trajectory) ↔ Rejected (incorrect trajectory). Pairs teach three distinct lessons.", {
    x: 0.35, y: 0.92, w: 9.3, h: 0.38,
    fontSize: 12.5, color: C.textMid, fontFace: "Calibri", align: "left", margin: 0
  });

  // Table
  const headers = ["Query", "Chosen →", "Rejected →", "Learning Lesson", "Count", "Difficulty"];
  const colX2 = [0.28, 1.45, 3.05, 4.65, 7.15, 8.3];
