    });
    s.addText(h, {
      x: colX2[i] + 0.05, y: 1.39, w: colW2[i] - 0.1, h: 0.35,
      fontSize: 10, bold: true, color: C.tealLt,
      fontFace: "Calibri", align: "left", valign: "middle", margin: 0
    });
  });

  const tableRows = [
    ["Type 1", "1→3→4→5", "1→2→3→4→5", "Prevent redundant\nslot-filling", "2,089", "Easy"],
    ["Type 1", "1→3→4→5", "1→(2×N)→3→4→5", "Prevent redundant\nslot-filling", "562", "Hard"],
    ["Type 1", "1→3→4→5", "1→(2×M)→3→4→5", "Prevent redundant\nslot-filling", "2,530", "Hard"],
    ["Type 1", "1→3→4→5", "1→1", "Tool call accept", "2,090 / 562", "Easy / Hard"],
    ["Type 2", "1→2→3→4→5", "1→3→4→5", "Prevent slot\nhallucination", "2,089", "Easy"],
    ["Type 2", "1→(2×N)→3→4→5", "1→3→4→5", "Prevent slot\nhallucination", "562", "Hard"],
